		gameWS.onmessage=function(k){
		
		var tmpMess=k.data.split("#");

		
			if(tmpMess[0]=='UPDATE' && gameController.win<=0 && gameController.kha.dxy!=undefined){
			
			if(gameController.eli!=parseInt(tmpMess[1])){
				
			gameController.eli=parseInt(tmpMess[1]);	
			gameController.kha.dxy.xhe("creditd", "#loi", [gameController.uom(tmpMess[1]), true]);	
			
			}
			
			
			
			
			
			}	
			
		}
		
